#!/bin/bash
# launch_@ARM@.sh -- measurement arm @ARM@ of the hypothesis-1 trace @MODEL@/@CFG@: the ref_mcm config of the same directory with
# the first-touch placement dump replaced by a load of ../ref_mcm/placement_mcm.map (base_mcm), plus
# "-icnt_ptw_ring_hop_latency 0" (ptwhop0_mcm). Same tree, 16 threads (user instruction 2026-11-09: 16-thread arms, at most two
# at once). Generated by llm_exp/scripts/h1_make_arm.sh from h1_arm_launch_template.sh. Waits for ref_mcm to finish with a
# placement map; the run itself is a child shell (@ARM@/run.sh, no set -u). Run inside mcm-accelsim as uid 1035.
# env DRY=1: preflight only.
set -u
P=/accel-sim/llm_exp/llm_hypothesis1/@MODEL@/@CFG@
X=$P/sim/@ARM@
REF=$P/sim/ref_mcm
TREE=/accel-sim/llm_exp/llm_sim_tree_pwcstat_l1fwd
BIN=$TREE/gpu-simulator/bin/release/accel-sim.out
SO=$TREE/gpu-simulator/gpgpu-sim/lib/gcc-11.4.0/cuda-12020/release/libcudart.so
BIN_MD5=b4876c28ad2e290989c6460f86498e4c; SO_MD5=dbaed8e6c2c9b9ca20c23fc163cfe513
TRACE=$P/traces/kernelslist.g
EXPECT_HOP=@EXPECT_HOP@      # -1 for base_mcm (config default), 0 for ptwhop0_mcm
TH=${TH:-16}; DRY=${DRY:-0}
LOG=$P/sim/launch_@ARM@.log
log(){ echo "$(date '+%F %T') [h1_@CFG@_@ARM@] $*" | tee -a $LOG; }
die(){ log "ABORT: $*"; echo "ABORT @ARM@ $*" >> $P/sim/status.txt; exit 1; }
md5(){ md5sum "$1" | awk '{print $1}'; }
exec {LK}>$P/sim/.launch_@ARM@.lock
flock -n $LK || { echo "another launch_@ARM@.sh holds the lock"; exit 1; }

# ---------- gate: ref_mcm finished and dumped its placement map ----------
log "waiting for $REF/exit_code.txt"
until [ -s $REF/exit_code.txt ]; do sleep 60; done
grep -q '^EXIT=0 ' $REF/exit_code.txt || die "ref_mcm did not finish cleanly: $(cat $REF/exit_code.txt)"
[ -s $REF/placement_mcm.map ] && grep -q '^\[PLACEMENT\] dump: ./placement_mcm.map' $REF/run.log || die "ref_mcm placement map missing"
log "ref_mcm done: $(cat $REF/exit_code.txt); map $(wc -l < $REF/placement_mcm.map) lines"

# ---------- preflight ----------
[ "$(md5 $BIN)" = $BIN_MD5 ] || die "binary md5 $(md5 $BIN) != $BIN_MD5"
[ "$(md5 $SO)" = $SO_MD5 ] || die "libcudart.so md5 $(md5 $SO) != $SO_MD5"
nd=$(diff $REF/gpgpusim.config $X/gpgpusim.config | grep -c '^[<>]')
if [ "@ARM@" = base_mcm ]; then
  [ "$nd" = 2 ] && diff $REF/gpgpusim.config $X/gpgpusim.config | grep -qx -- '> -gmmu_placement_load ../ref_mcm/placement_mcm.map' \
    || die "base_mcm is not ref_mcm with only the placement line changed ($nd diff lines)"
else
  [ "$nd" = 3 ] && diff $REF/gpgpusim.config $X/gpgpusim.config | grep -qx -- '> -gmmu_placement_load ../ref_mcm/placement_mcm.map' \
    && diff $REF/gpgpusim.config $X/gpgpusim.config | grep -qx -- '> -icnt_ptw_ring_hop_latency 0' \
    || die "ptwhop0_mcm is not ref_mcm + placement load + PTW hop 0 ($nd diff lines)"
fi
if grep -qx -- '-gpgpu_max_insn 0' $X/gpgpusim.config; then
  [ -s $X/CAP_EXCEPTION.txt ] || die "cap 0 without CAP_EXCEPTION.txt"
fi
cmp -s $REF/trace.config $X/trace.config && cmp -s $REF/config_ampere_islip.icnt $X/config_ampere_islip.icnt || die "trace.config / icnt differ from ref_mcm"
[ -x $X/run.sh ] || die "run.sh missing"
[ -e $X/run.log ] && die "run.log already exists -- refusing to overwrite"
log "preflight OK: arm=@ARM@ diff_lines=$nd bin=$BIN_MD5 cfg=$(md5 $X/gpgpusim.config) trace=$(md5 $TRACE) threads=$TH dry=$DRY"
[ "$DRY" = 1 ] && { log "DRY run finished -- nothing launched"; exit 0; }

# ---------- run (child shell without set -u) ----------
echo "RUNNING @ARM@ $(date '+%F %T')" >> $P/sim/status.txt
log "@ARM@ start (threads $TH)"
TH=$TH bash $X/run.sh
cd $X
log "@ARM@ end: $(cat exit_code.txt 2>/dev/null)"
bad=""
grep -q '^EXIT=0 ' exit_code.txt 2>/dev/null || bad="$bad exit"
grep -q '^\[PLACEMENT\] load: ../ref_mcm/placement_mcm.map' run.log || bad="$bad placement_load"
grep -qE "^-icnt_ptw_ring_hop_latency[[:space:]]+$EXPECT_HOP " run.log || bad="$bad ptw_hop"
grep -qE '^-gpgpu_lasp_policy[[:space:]]+4 ' run.log || bad="$bad lasp"
grep -qE '^-gpgpu_cta_chiplet_cursor[[:space:]]+1 ' run.log || bad="$bad cursor"
grep -q 'per-chiplet cursors on' run.log || bad="$bad pcc_line"
if [ -z "$bad" ]; then echo "DONE @ARM@ $(date '+%F %T')" >> $P/sim/status.txt; log "@ARM@ finished, option check OK (placement=load ptw_hop=$EXPECT_HOP lasp=4 cursor=1)"
else echo "FAILED @ARM@ $(date '+%F %T')" >> $P/sim/status.txt; log "@ARM@ option check FAILED:$bad"; fi
